// Outer page frame shared by every plot tool. Renders the AppBar (step nav,
// file chip, and on the plot step the export bar the tool's ActionsPanel
// registers plus PrefsPanel), the comma-fix / formula-injection / parse-error
// banners, and delegates everything else to children — each tool still owns
// the per-step content (UploadStep, ConfigureStep, the plot workspace, etc.)
// since those differ per tool.
//
import type { PlotToolState } from "./usePlotToolState";
import { PrefsPanel } from "./PrefsPanel";
import { AppBar, FileChip } from "./AppBar";
import { StepNavBar } from "./StepNavBar";
import { CommaFixBanner } from "./CommaFixBanner";
import { FormulaInjectionBanner } from "./FormulaInjectionBanner";
import { ParseErrorBanner } from "./ParseErrorBanner";
import { PlotActionsBar } from "./PlotActionsBar";
import {
  PlotActionsContext,
  plotActionsSignature,
  type PlotActionsEntry,
  type PlotActionsRegistry,
} from "./plot-actions";

const { useEffect, useMemo, useRef, useState } = React;

interface PlotToolShellProps<TVis extends object> {
  state: PlotToolState<TVis>;
  toolName: string;
  title: string;
  visInit: TVis;
  steps: string[];
  canNavigate: (target: string) => boolean;
  // Optional override for the step label shown in the nav bar. Useful when a
  // step's *purpose* varies with dataset shape (e.g. venn's step 2 is just an
  // import check with ≤ 3 sets but becomes a real configure flow with ≥ 4).
  // Keys = step identifiers (unchanged); values = human-readable labels.
  stepLabels?: Record<string, string>;
  children: React.ReactNode;
}

// 120 ms opacity fade on step change. Tracks the current step in a ref so the
// first mount doesn't fade in, and respects prefers-reduced-motion (no fade).
function StepFade({ step, children }: { step: string; children: React.ReactNode }) {
  const [opacity, setOpacity] = useState(1);
  const prevStep = useRef(step);
  const reduceMotion =
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  useEffect(() => {
    if (prevStep.current === step || reduceMotion) {
      prevStep.current = step;
      return undefined;
    }
    prevStep.current = step;
    setOpacity(0);
    const id = window.setTimeout(() => setOpacity(1), 10);
    return () => window.clearTimeout(id);
  }, [step, reduceMotion]);
  return (
    <div style={{ opacity, transition: reduceMotion ? "none" : "opacity 120ms ease-out" }}>
      {children}
    </div>
  );
}

export function PlotToolShell<TVis extends object>({
  state,
  toolName,
  title,
  visInit,
  steps,
  canNavigate,
  stepLabels,
  children,
}: PlotToolShellProps<TVis>) {
  // The plot step's ActionsPanel registers its downloads + reset here; the
  // header renders them (see plot-actions.ts). `sig` re-renders the header
  // only when the visible buttons change.
  const actionsRef = useRef<PlotActionsEntry | null>(null);
  const [, setSig] = useState("");
  const registry = useMemo<PlotActionsRegistry>(
    () => ({
      set: (entry) => {
        actionsRef.current = entry;
        const next = plotActionsSignature(entry);
        setSig((prev) => (prev === next ? prev : next));
      },
    }),
    []
  );
  const onPlot = state.step === "plot";
  // The plot step is a `WorkspaceLayout` that fills the window edge to edge.
  const fullBleed = onPlot;
  return (
    <div className="dv-tool" data-tool-key={toolName}>
      {/* The visible tool name lives in the app bar's switcher button; the
          page heading stays for screen readers and the document outline. */}
      <h1 className="dv-sr-only">{title}</h1>
      <AppBar
        steps={
          <StepNavBar
            steps={steps}
            currentStep={state.step}
            onStepChange={state.setStep}
            canNavigate={canNavigate}
            stepLabels={stepLabels}
          />
        }
        actions={
          state.step !== "upload" ? (
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <FileChip name={state.fileName} />
              {onPlot && <PlotActionsBar entryRef={actionsRef} />}
              {onPlot && (
                <PrefsPanel
                  tool={toolName}
                  vis={state.vis}
                  visInit={visInit}
                  updVis={state.updVis}
                />
              )}
            </div>
          ) : null
        }
      />
      <main
        className={fullBleed ? "dv-tool-body dv-tool-body-full" : "dv-tool-body"}
        style={
          fullBleed
            ? undefined
            : {
                padding: onPlot ? "20px 24px 32px" : "28px 32px 48px",
                maxWidth: 1400,
                margin: "0 auto",
              }
        }
      >
        <CommaFixBanner commaFixed={state.commaFixed} commaFixCount={state.commaFixCount} />
        <FormulaInjectionBanner warning={state.injectionWarning} />
        <ParseErrorBanner error={state.parseError} />
        <PlotActionsContext.Provider value={registry}>
          <StepFade step={state.step}>{children}</StepFade>
        </PlotActionsContext.Provider>
      </main>
    </div>
  );
}
